messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: a low-poly 3D humanoid figure performs this exact cycle on a treadmill-style ground, side-on camera: stands still for 2 seconds, walks in place for 3 seconds (limbs swinging at walking pace), runs in place for 3 seconds (faster, larger limb swings, slight forward lean), then stands still again for 2 seconds. The 10-second cycle loops forever and must start immediately on load. Limb movement must clearly differ between walking and running. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Low-Poly Treadmill Animation</title>
    <style>
        body { margin: 0; overflow: hidden; background: #87CEEB; }
        canvas { display: block; }
        #info {
            position: absolute;
            top: 20px;
            left: 20px;
            color: white;
            font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
            font-size: 24px;
            font-weight: bold;
            text-shadow: 1px 1px 2px rgba(0,0,0,0.5);
            pointer-events: none;
        }
    </style>
</head>
<body>
    <div id="info">STAND</div>
    <script type="module">
        import * as THREE from './three.module.js';

        // --- Configuration ---
        const CYCLE_DURATION = 10; // seconds
        const STAND_TIME = 2;
        const WALK_TIME = 3;
        const RUN_TIME = 3;

        // --- Scene Setup ---
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x87CEEB); // Sky blue
        scene.fog = new THREE.Fog(0x87CEEB, 10, 50);

        const camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.1, 100);
        camera.position.set(0, 1.5, 6);
        camera.lookAt(0, 1, 0);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.shadowMap.enabled = true;
        renderer.shadowMap.type = THREE.PCFSoftShadowMap;
        document.body.appendChild(renderer.domElement);

        // --- Lighting ---
        const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffffff, 1.5);
        dirLight.position.set(-5, 10, 5);
        dirLight.castShadow = true;
        dirLight.shadow.mapSize.width = 1024;
        dirLight.shadow.mapSize.height = 1024;
        scene.add(dirLight);

        // --- Materials ---
        const skinMat = new THREE.MeshStandardMaterial({ color: 0xffccaa, flatShading: true });
        const shirtMat = new THREE.MeshStandardMaterial({ color: 0xff5555, flatShading: true });
        const pantsMat = new THREE.MeshStandardMaterial({ color: 0x5555ff, flatShading: true });
        const shoeMat = new THREE.MeshStandardMaterial({ color: 0x333333, flatShading: true });
        const treadmillMat = new THREE.MeshStandardMaterial({ color: 0x444444, flatShading: true });
        const beltMat = new THREE.MeshStandardMaterial({ color: 0x222222, flatShading: true });

        // --- Build Humanoid ---
        const human = new THREE.Group();
        const root = new THREE.Group(); // For body lean
        human.add(root);

        // Torso
        const torsoGeo = new THREE.BoxGeometry(0.5, 0.7, 0.3);
        const torso = new THREE.Mesh(torsoGeo, shirtMat);
        torso.position.y = 1.35;
        torso.castShadow = true;
        root.add(torso);

        // Head
        const headGeo = new THREE.BoxGeometry(0.3, 0.3, 0.3);
        const head = new THREE.Mesh(headGeo, skinMat);
        head.position.y = 0.55;
        head.castShadow = true;
        torso.add(head);

        // Limbs Helper
        function createLimb(width, height, depth, material, yOffset) {
            const group = new THREE.Group();
            group.position.y = yOffset;
            const geo = new THREE.BoxGeometry(width, height, depth);
            const mesh = new THREE.Mesh(geo, material);
            // Pivot point is at the top of the limb
            mesh.position.y = -height / 2;
            mesh.castShadow = true;
            group.add(mesh);
            return group;
        }

        // Arms
        const leftArm = createLimb(0.15, 0.6, 0.15, skinMat, 0.3); // Shoulder height relative to torso
        const rightArm = createLimb(0.15, 0.6, 0.15, skinMat, 0.3);
        root.add(leftArm);
        root.add(rightArm);

        // Legs
        const leftLeg = createLimb(0.2, 0.7, 0.2, pantsMat, -0.35); // Hip height relative to torso
        const rightLeg = createLimb(0.2, 0.7, 0.2, pantsMat, -0.35);
        root.add(leftLeg);
        root.add(rightLeg);

        // Shoes (Children of legs to swing with them)
        const shoeGeo = new THREE.BoxGeometry(0.22, 0.1, 0.35);
        const leftShoe = new THREE.Mesh(shoeGeo, shoeMat);
        leftShoe.position.y = -0.7; // Bottom of leg
        leftShoe.position.z = 0.05;  // Slightly forward
        leftLeg.add(leftShoe);

        const rightShoe = new THREE.Mesh(shoeGeo, shoeMat);
        rightShoe.position.y = -0.7;
        rightShoe.position.z = 0.05;
        rightLeg.add(rightShoe);

        scene.add(human);

        // --- Build Treadmill ---
        const treadmillGroup = new THREE.Group();

        // Frame
        const frameGeo = new THREE.BoxGeometry(3, 0.1, 1.2);
        const frame = new THREE.Mesh(frameGeo, treadmillMat);
        frame.position.y = 0.05;
        frame.castShadow = true;
        frame.receiveShadow = true;
        treadmillGroup.add(frame);

        // Belt
        const beltGeo = new THREE.PlaneGeometry(2.5, 1);
        const belt = new THREE.Mesh(beltGeo, beltMat);
        belt.rotation.x = -Math.PI / 2;
        belt.position.y = 0.11;
        belt.receiveShadow = true;
        treadmillGroup.add(belt);

        // Console (Simple box)
        const consoleGeo = new THREE.BoxGeometry(0.4, 0.8, 0.8);
        const consoleMesh = new THREE.Mesh(consoleGeo, treadmillMat);
        consoleMesh.position.set(1.2, 0.5, 0);
        consoleMesh.castShadow = true;
        treadmillGroup.add(consoleMesh);

        scene.add(treadmillGroup);

        // --- Animation Logic ---
        const infoEl = document.getElementById('info');

        // Easing function for smoother transitions
        function easeInOutSine(x) {
            return -(Math.cos(Math.PI * x) - 1) / 2;
        }

        // Limb animation function
        function animateLimb(limb, phase, amplitude, offset) {
            // Swing back and forth
            const angle = Math.sin(phase) * amplitude;
            // Add a slight bend (rotation around Z) when swinging
            const bend = Math.abs(Math.sin(phase)) * amplitude * 0.5;

            limb.rotation.z = angle;
            // Slight forward/backward rotation for 3D effect
            limb.rotation.y = Math.sin(phase) * amplitude * 0.2;
        }

        function animate(time) {
            // Time is in seconds
            const cycleTime = time % CYCLE_DURATION;
            let state = '';
            let phase = 0;
            let speed = 0;
            let legAmp = 0;
            let armAmp = 0;
            let bodyLean = 0;

            if (cycleTime < STAND_TIME) {
                state = 'STAND';
                speed = 0;
                legAmp = 0;
                armAmp = 0;
                bodyLean = 0;
            } else if (cycleTime < STAND_TIME + WALK_TIME) {
                state = 'WALKING';
                const t = (cycleTime - STAND_TIME) / WALK_TIME;
                // Walk speed: ~1 cycle per second
                speed = 2 * Math.PI; 
                phase = time * speed;
                // Walking amplitude: moderate
                legAmp = 0.4; // ~23 degrees
                armAmp = 0.3; // ~17 degrees
                bodyLean = 0.05; // Slight forward lean
            } else if (cycleTime < STAND_TIME + WALK_TIME + RUN_TIME) {
                state = 'RUNNING';
                const t = (cycleTime - STAND_TIME - WALK_TIME) / RUN_TIME;
                // Run speed: ~2.5 cycles per second
                speed = 5 * Math.PI;
                phase = time * speed;
                // Running amplitude: large
                legAmp = 0.7; // ~40 degrees
                armAmp = 0.6; // ~34 degrees
                bodyLean = 0.15; // More forward lean
            } else {
                // Final part of the last stand (handled by first if, but just in case)
                state = 'STAND';
                speed = 0;
                legAmp = 0;
                armAmp = 0;
                bodyLean = 0;
            }

            // Update UI
            infoEl.textContent = state;
            infoEl.style.color = state === 'STAND' ? '#FFFFFF' : (state === 'WALKING' ? '#FFDD55' : '#FF5555');

            // Apply animations
            if (state === 'STAND') {
                // Reset poses
                leftLeg.rotation.z = 0;
                rightLeg.rotation.z = 0;
                leftArm.rotation.z = 0;
                rightArm.rotation.z = 0;
                root.rotation.z = 0;
            } else {
                // Animate limbs
                // Legs: Out of phase (one forward, one back)
                animateLimb(leftLeg, phase, legAmp, 0);
                animateLimb(rightLeg, phase, legAmp, Math.PI);

                // Arms: Opposite phase to legs (Right arm with Left leg)
                animateLimb(leftArm, phase, armAmp, Math.PI);
                animateLimb(rightArm, phase, armAmp, 0);

                // Body Lean
                root.rotation.z = bodyLean;
            }

            // Animate Treadmill Belt
            // Speed of belt matches the speed of the runner's feet relative to the ground
            // We can just animate the texture offset or simply rotate a cylinder, but since it's a plane:
            // Let's create a simple visual effect by moving a grid or just pulsing the color if we want simple
            // Better: Add a grid helper to the belt and move it
            if (!belt.userData.grid) {
                const gridHelper = new THREE.GridHelper(2.5, 10, 0x555555, 0x555555);
                gridHelper.rotation.x = -Math.PI / 2;
                gridHelper.position.y = 0.01;
                belt.add(gridHelper);
                belt.userData.grid = gridHelper;
            }

            // Move grid to simulate movement
            const beltSpeed = (state === 'WALKING') ? 0.5 : (state === 'RUNNING') ? 1.2 : 0;
            belt.userData.grid.position.z -= beltSpeed * 0.05;
            if (belt.userData.grid.position.z < -0.5) {
                belt.userData.grid.position.z = 0.5;
            }

            renderer.render(scene, camera);
            requestAnimationFrame(animate);
        }

        // Handle Window Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        // Start Animation
        const startTime = performance.now() / 1000;
        animate(startTime);
    </script>
</body>
</html>
```
